const SESSION_DAYS = 30;
const COOKIE_NAME = "tp_session";

function json(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" }
  });
}

async function sha256Hex(text) {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text));
  return [...new Uint8Array(digest)].map(b => b.toString(16).padStart(2, "0")).join("");
}

function randomToken(bytes = 32) {
  const a = new Uint8Array(bytes);
  crypto.getRandomValues(a);
  return [...a].map(b => b.toString(16).padStart(2, "0")).join("");
}

async function passwordHash(password, salt = randomToken(16)) {
  const key = await crypto.subtle.importKey("raw", new TextEncoder().encode(password), "PBKDF2", false, ["deriveBits"]);
  const bits = await crypto.subtle.deriveBits({ name: "PBKDF2", salt: new TextEncoder().encode(salt), iterations: 120000, hash: "SHA-256" }, key, 256);
  return `pbkdf2$120000$${salt}$${[...new Uint8Array(bits)].map(b => b.toString(16).padStart(2, "0")).join("")}`;
}

async function passwordVerify(password, stored) {
  const parts = String(stored || "").split("$");
  if (parts.length !== 4 || parts[0] !== "pbkdf2") return false;
  const iterations = Number(parts[1]);
  if (!iterations || iterations < 1) return false;
  const key = await crypto.subtle.importKey("raw", new TextEncoder().encode(password), "PBKDF2", false, ["deriveBits"]);
  const bits = await crypto.subtle.deriveBits({ name: "PBKDF2", salt: new TextEncoder().encode(parts[2]), iterations, hash: "SHA-256" }, key, 256);
  const hex = [...new Uint8Array(bits)].map(b => b.toString(16).padStart(2, "0")).join("");
  return hex === parts[3];
}

function cookies(request) {
  const out = {};
  const raw = request.headers.get("Cookie") || "";
  for (const part of raw.split(";")) {
    const i = part.indexOf("=");
    if (i > -1) out[part.slice(0, i).trim()] = decodeURIComponent(part.slice(i + 1).trim());
  }
  return out;
}

function sessionCookie(token, maxAge = SESSION_DAYS * 86400) {
  return `${COOKIE_NAME}=${encodeURIComponent(token)}; Path=/; Max-Age=${maxAge}; HttpOnly; Secure; SameSite=Lax`;
}

async function body(request) {
  try {
    const x = await request.json();
    return x && typeof x === "object" ? x : {};
  } catch { return {}; }
}

function defaultPlanner() {
  return {
    settings: {
      target: 8000,
      currency: "£",
      categories: [
        { id: "c1", name: "Full Day", price: 600 },
        { id: "c2", name: "Média", price: 200 },
        { id: "c3", name: "Minimum", price: 80 }
      ]
    },
    bookings: {}
  };
}

async function currentUser(request, env) {
  const token = cookies(request)[COOKIE_NAME];
  if (!token) return null;
  const tokenHash = await sha256Hex(token);
  const row = await env.DB.prepare(`
    SELECT u.id, u.email, u.name
    FROM sessions s JOIN users u ON u.id = s.user_id
    WHERE s.token_hash = ? AND s.expires_at > datetime('now')
  `).bind(tokenHash).first();
  return row || null;
}

async function createSession(userId, env) {
  const token = randomToken(32);
  const tokenHash = await sha256Hex(token);
  await env.DB.prepare(`DELETE FROM sessions WHERE expires_at <= datetime('now')`).run();
  await env.DB.prepare(`INSERT INTO sessions (token_hash, user_id, expires_at) VALUES (?, ?, datetime('now', '+30 days'))`).bind(tokenHash, userId).run();
  return token;
}

async function auth(request, env, url) {
  const action = url.searchParams.get("action") || "";
  if (action === "me") {
    const user = await currentUser(request, env);
    return json(user ? { loggedIn: true, user } : { loggedIn: false });
  }

  if (action === "logout") {
    const token = cookies(request)[COOKIE_NAME];
    if (token) await env.DB.prepare("DELETE FROM sessions WHERE token_hash = ?").bind(await sha256Hex(token)).run();
    return new Response(JSON.stringify({ ok: true }), { headers: { "content-type": "application/json", "set-cookie": sessionCookie("", 0) } });
  }

  const data = await body(request);
  const email = String(data.email || "").trim().toLowerCase();
  const password = String(data.password || "");

  if (action === "register") {
    const name = String(data.name || "").trim();
    if (!name || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) || password.length < 8) {
      return json({ error: "Enter your name, a valid email and a password of at least 8 characters." }, 422);
    }
    const existing = await env.DB.prepare("SELECT id FROM users WHERE email = ?").bind(email).first();
    if (existing) return json({ error: "That email is already registered." }, 409);
    const hash = await passwordHash(password);
    const result = await env.DB.prepare("INSERT INTO users (email, name, password_hash) VALUES (?, ?, ?)").bind(email, name, hash).run();
    const id = result.meta.last_row_id;
    await env.DB.prepare("INSERT INTO planner_data (user_id, data_json) VALUES (?, ?)").bind(id, JSON.stringify(defaultPlanner())).run();
    const token = await createSession(id, env);
    return new Response(JSON.stringify({ ok: true, user: { id, email, name } }), {
      headers: { "content-type": "application/json", "set-cookie": sessionCookie(token) }
    });
  }

  if (action === "login") {
    if (!email || !password) return json({ error: "Enter your email and password." }, 422);
    const user = await env.DB.prepare("SELECT id, email, name, password_hash FROM users WHERE email = ?").bind(email).first();
    if (!user || !(await passwordVerify(password, user.password_hash))) return json({ error: "Incorrect email or password." }, 401);
    const token = await createSession(user.id, env);
    return new Response(JSON.stringify({ ok: true, user: { id: user.id, email: user.email, name: user.name } }), {
      headers: { "content-type": "application/json", "set-cookie": sessionCookie(token) }
    });
  }

  return json({ error: "Unknown action." }, 404);
}

async function dataApi(request, env) {
  const user = await currentUser(request, env);
  if (!user) return json({ error: "Not logged in." }, 401);
  const method = request.method;
  if (method === "GET") {
    const row = await env.DB.prepare("SELECT data_json FROM planner_data WHERE user_id = ?").bind(user.id).first();
    let data = defaultPlanner();
    if (row?.data_json) {
      try { data = JSON.parse(row.data_json) || data; } catch {}
    } else {
      await env.DB.prepare("INSERT INTO planner_data (user_id, data_json) VALUES (?, ?)").bind(user.id, JSON.stringify(data)).run();
    }
    return json({ data });
  }
  if (method === "POST" || method === "PUT") {
    const b = await body(request);
    if (!b.data || typeof b.data !== "object") return json({ error: "Invalid planner data." }, 422);
    await env.DB.prepare("INSERT INTO planner_data (user_id, data_json, updated_at) VALUES (?, ?, datetime('now')) ON CONFLICT(user_id) DO UPDATE SET data_json=excluded.data_json, updated_at=datetime('now')").bind(user.id, JSON.stringify(b.data)).run();
    return json({ ok: true });
  }
  return json({ error: "Method not allowed." }, 405);
}

export default {
  async fetch(request, env) {
    try {
      const url = new URL(request.url);
      if (url.pathname === "/api/auth" || url.pathname === "/api/auth.php") return await auth(request, env, url);
      if (url.pathname === "/api/data" || url.pathname === "/api/data.php") return await dataApi(request, env);
      const bytes = Uint8Array.from(atob(""), c => c.charCodeAt(0));
      const html = new TextDecoder("utf-8").decode(bytes);
      return new Response(html, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" } });
    } catch (e) {
      console.error(e);
      return json({ error: e?.message || "Server error. Check the D1 binding and tables." }, 500);
    }
  }
};
